UPDATE public.brands SET logo_url = 'https://restaurant-ar.pages.dev/assets/kado/logo.webp', primary_color = '#e0333a', secondary_color = '#9e1b21' WHERE id = 75;

DO $$
BEGIN
  IF (SELECT count(*) FROM public.categories WHERE restaurant_id = 81) <> 15 THEN RAISE EXCEPTION 'expected 15 categories'; END IF;
  IF (SELECT count(*) FROM public.menu_items WHERE restaurant_id = 81) <> 143 THEN RAISE EXCEPTION 'expected 143 items'; END IF;
  IF (SELECT count(*) FROM public.menu_items WHERE restaurant_id = 81 AND thumbnail_url LIKE 'https://restaurant-ar.pages.dev/assets/kado/items/%.webp') <> 132 THEN RAISE EXCEPTION 'expected 132 thumbnails'; END IF;
  IF (SELECT count(*) FROM public.menu_items WHERE restaurant_id = 81 AND is_3d) <> 0 THEN RAISE EXCEPTION 'no 3D models exist yet'; END IF;
  IF EXISTS (SELECT 1 FROM public.menu_items m JOIN public.categories c ON c.id = m.category_id WHERE m.restaurant_id = 81 AND c.restaurant_id <> 81) THEN RAISE EXCEPTION 'cross-tenant category'; END IF;
END $$;

SELECT c.sort_order, c.name_en, count(m.id) AS items FROM public.categories c LEFT JOIN public.menu_items m ON m.category_id = c.id WHERE c.restaurant_id = 81 GROUP BY c.id ORDER BY c.sort_order;

ROLLBACK;
